    #[test]
    fn provider_map_capacity_is_atomic_and_cpu_charged_before_loading() {
        let maps: Vec<_> = specs()
            .into_iter()
            .map(|m| loader::MapSpecLite {
                name: m.name.into(),
                map_type: m.map_type,
                key_size: m.key_size,
                value_size: m.value_size,
                max_entries: m.max_entries,
                flags: m.flags,
            })
            .collect();
        // Independent fixed total for the actual eighteen ordinary provider maps
        // on sixteen possible CPUs, excluding the separately owned ADMIT gate
        // (T8.2a: TRACE_MODE adds (4 + 8 + 128) * 1 + 65536 = 65676;
        // fix4: CONFIG value 24 -> 32 adds (8 + 32 + 128 - 160) * 1024 = 8192;
        // fix5: INV_SEQ adds (4 + 8 + 128) * 1 + 65536 = 65676;
        // fix6: THREADS + API_THREADS values 16 -> 24 add 8 * 4096 * 2 = 65536;
        // fix7: THREADS + API_THREADS values 24 -> 32 add 8 * 4096 * 2 = 65536;
        // R10 1b: THREADS + API_THREADS values 32 -> 40 add 8 * 4096 * 2 = 65536;
        // Round-5 N2: THREADS + API_THREADS values 40 -> 48 add 8 * 4096 * 2 = 65536;
        // Round-6 1a: THREADS + API_THREADS values 48 -> 64 add 16 * 4096 * 2 = 131072).
        let required = 7_699_120;
        let budget = ObservationBudget::new(ObservationLimits {
            max_state_bytes: required - 1,
            ..Default::default()
        });
        assert_eq!(
            reserve_map_capacity(&budget, &maps, 16),
            Err(ObservationGap::StateLimit)
        );
        budget.state(required - 1).unwrap(); // failed batch did not consume a prefix
        let budget = ObservationBudget::new(ObservationLimits {
            max_state_bytes: required,
            ..Default::default()
        });
        reserve_map_capacity(&budget, &maps, 16).unwrap();
        assert_eq!(budget.state(1), Err(ObservationGap::StateLimit));
        let budget = ObservationBudget::default();
        assert_eq!(
            reserve_map_capacity(&budget, &maps, usize::MAX),
            Err(ObservationGap::StateLimit)
        );
    }

